// Normalise Cal.com BOOKING_CREATED payload — handle both v1 and v2 shapes.
const body = $input.first().json;
const payload = body.payload ?? body;

const attendee = Array.isArray(payload.attendees) ? payload.attendees[0] : null;
const email = (attendee?.email ?? payload.bookerEmail ?? payload.email ?? '').toLowerCase().trim();
const firstName = attendee?.name?.split(' ')[0] ?? payload.bookerName?.split(' ')[0] ?? '';
const lastName = attendee?.name?.split(' ').slice(1).join(' ') ?? payload.bookerName?.split(' ').slice(1).join(' ') ?? '';
const eventTitle = payload.title ?? payload.eventTitle ?? 'Discovery Call';
const startTime = payload.startTime;
const bookingUid = payload.uid ?? payload.bookingUid ?? '';

const vtigerUrl = $env.VTIGER_URL?.replace(/\/$/, '') ?? '';
const vtigerUser = $env.VTIGER_USERNAME ?? '';
const vtigerKey = $env.VTIGER_ACCESS_KEY ?? '';

if (!vtigerUrl || !vtigerUser || !vtigerKey) {
  throw new Error('Vtiger env vars (VTIGER_URL, VTIGER_USERNAME, VTIGER_ACCESS_KEY) are not set in n8n');
}

return [{
  json: {
    email,
    firstName,
    lastName,
    eventTitle,
    startTime,
    bookingUid,
    vtigerUrl,
    vtigerUser,
    vtigerKey,
  }
}];

// Compute MD5(challenge_token + access_key) and POST login.
// Returns sessionName for downstream nodes.
const prep = $('Prepare: Extract Booking Data').first().json;
const challenge = $input.first().json;

if (!challenge.success) throw new Error('Vtiger getchallenge failed: ' + JSON.stringify(challenge));

const token = challenge.result.token;
const { createHash } = require('crypto');
const accessKeyHash = createHash('md5').update(token + prep.vtigerKey).digest('hex');

return [{
  json: {
    ...prep,
    loginToken: token,
    accessKeyHash,
  }
}];

// Extract sessionName and prepare VQL to find contact by email.
const prep = $('Prepare: Build Login Hash').first().json;
const loginResult = $input.first().json;

if (!loginResult.success) throw new Error('Vtiger login failed: ' + JSON.stringify(loginResult));

const sessionName = loginResult.result.sessionName;
const safeEmail = prep.email.replace(/'/g, "\\'");
const query = encodeURIComponent(`SELECT * FROM Contacts WHERE email='${safeEmail}' LIMIT 1`);

return [{
  json: {
    ...prep,
    sessionName,
    query,
  }
}];

// Build new Contacts payload.
const prep = $('Prepare: Session + Query').first().json;
const element = JSON.stringify({
  email: prep.email,
  firstname: prep.firstName || prep.email.split('@')[0],
  lastname: prep.lastName || '',
  leadsource: 'Discovery Call',
  cf_pipeline_stage: 'Discovery Call Booked',
});
return [{ json: { ...prep, element } }];

// Merge contact ID from both branches.
const prep = $('Prepare: Session + Query').first().json;

// Try find-result first, fall back to create-result
let contactId = null;
try {
  const findResult = $('Vtiger: Find Contact By Email').first().json;
  if (findResult.success && findResult.result?.length > 0) {
    contactId = findResult.result[0].id;
  }
} catch {}

if (!contactId) {
  const createResult = $input.first().json;
  if (createResult.success) {
    contactId = createResult.result?.id ?? null;
  }
}

if (!contactId) throw new Error('Could not find or create Vtiger contact for ' + prep.email);

return [{ json: { ...prep, contactId } }];

// Build Activity payload.
const prep = $input.first().json;
const bookingDate = prep.startTime
  ? new Date(prep.startTime).toISOString().slice(0, 10)
  : new Date().toISOString().slice(0, 10);
const bookingTime = prep.startTime
  ? new Date(prep.startTime).toTimeString().slice(0, 8)
  : new Date().toTimeString().slice(0, 8);

const subject = `Discovery Call — ${prep.eventTitle}`;
const element = JSON.stringify({
  activitytype: 'Call',
  subject,
  description: `Cal.com booking UID: ${prep.bookingUid}`,
  contact_id: prep.contactId,
  date_start: bookingDate,
  time_start: bookingTime,
  eventstatus: 'Planned',
});

return [{ json: { ...prep, element } }];

// Update pipeline stage to 'Discovery Call Booked'.
const prep = $('Merge: Resolve Contact ID').first().json;
const element = JSON.stringify({
  id: prep.contactId,
  cf_pipeline_stage: 'Discovery Call Booked',
});
return [{ json: { ...prep, element } }];

const prep = $('Merge: Resolve Contact ID').first().json;
console.log('[calcom-vtiger] SUCCESS contactId=' + prep.contactId + ' email=' + prep.email + ' event=' + prep.eventTitle);
return [$input.first()];

// Error handler — log to console (Sentry alert via Resend).
const errItem = $input.first();
const errorMessage = errItem.error?.message ?? errItem.json?.message ?? 'Unknown error';

let email = 'unknown';
try { email = $('Prepare: Extract Booking Data').first().json.email ?? 'unknown'; } catch {}

console.error('[calcom-vtiger] ERROR email=' + email + ' error=' + errorMessage);

return [{
  json: {
    email,
    errorMessage,
    subject: '[ALERT] Cal.com → Vtiger sync failed for ' + email,
    timestamp: new Date().toISOString(),
  }
}];
